import sys, re
sys.path.insert(0, "outputs/prior-capture/work")
from cap import Fill, _clean
c = Fill(39, "M02")
S = lambda key, text, lines, **kw: c.f(key, kw.pop("kind", "statement"), text, lines, **kw)
S("k21", "The heavy or hard hand, chains, sword and breath (kaved, qashah, qasheh: 1Sa 5:6, 5:7, 5:11; Psa 32:4; Lam 3:7; Isa 27:1, 27:8; Isa 30:27; Jer 20:7; Mat 25:24; Mal 3:13) is spoken of by humans under it, or by the narrator describing them; in this set God never calls his own hand heavy or hard; it is framed as experience: terror, affliction, wasting, being walled in, fear.", [21])
S("k22", "The \"strong / mighty hand and outstretched arm\" (chazaq) is the Exodus formula (Exo 6:1; 13:9; Deu 3:24; 4:34; 5:15; 6:21; 7:8; 7:19; 9:26; 11:2; 26:8; Jos 4:24; 1Ki 8:42; 2Ch 6:32; Neh 1:10; Psa 89:13; 136:12; Isa 40:10; Jer 21:5; 32:21; 50:34; Eze 20:33-34; Dan 9:15; Exo 32:11; Pro 23:11), spoken by God, Moses, the creed and prayers; it is framed as deliverance remembered, taught to children (Deu 6:21), and pleaded in prayer (Deu 9:26; Dan 9:15).", [22])
S("a29", "The Philistines under the ark: \"his hand is hard against us and against Dagon our god\" (1Sa 5:7); the narrator states the experience (\"heavy ... he terrified and afflicted them\", 5:6; \"a deathly panic ... very heavy\", 5:11), and the Philistines read it as intent to kill: \"to kill us and our people\" (5:10).", [29])
S("a30", "The psalmist: \"day and night your hand was heavy upon me; my strength was dried up\" (Psa 32:4); the context gives the cause inside the psalmist, \"when I kept silent, my bones wasted away\" (32:3); the heaviness ends at confession, \"I acknowledged my sin ... and you forgave\" (32:5); the psalm opens with the outcome God intended: \"Blessed is the one whose transgression is forgiven\" (32:1).", [30])
S("a32", "Lam 3: \"He has made my chains heavy ... he shuts out my prayer ... He is a bear lying in wait for me\" (3:7-10); the same poem then says \"the Lord will not cast off forever, for, though he cause grief, he will have compassion according to the abundance of his steadfast love; for he does not afflict from his heart\" (3:31-33): the chains are felt as heavy, and the poet confesses that the affliction does not come from God's heart; here the action and the heart are explicitly not the same.", [32], flag="the comment paragraphs, lines 33-34")
S("a35", "Mat 25:24-26: \"Master, I knew you to be a hard man\"; the servant names the source of his perception himself, \"so I was afraid, and I went and hid your talent\" (25:25); the master answers \"You wicked and slothful servant!\" (25:26): the perception of hardness is born of fear, and the parable condemns it.", [35])
S("a36", "Isa 59:1-2: \"the Lord's hand is not shortened, that it cannot save, or his ear dull [kaved]\"; the felt absence of God's hand has a stated cause, \"your iniquities have made a separation between you and your God, and your sins have hidden his face from you\": what is felt as God's weakness or deafness is the human separation.", [36])
S("a37", "Mal 3:13-15: \"Your words have been hard against me\"; the hard words are the human verdict on God, \"It is vain to serve God ... Evildoers ... prosper\"; the hardness is in the human perception of God's ways, and 3:16 answers with those who feared the Lord and \"a book of remembrance\".", [37])
S("a38", "The one who is overpowered for good perceives God as stronger, not as hard: \"O Lord, you have deceived me ... you are stronger than I, and you have prevailed\" (Jer 20:7); the force is the word, \"a burning fire shut up in my bones\" (20:9); the perception is of a strength he cannot resist, not of cruelty.", [38], basis="read")
S("a39", "The same hand is \"hard\" or \"saving\" depending on which side one stands: toward Egypt it is \"great deeds of terror\" (Deu 4:34; 26:8; Jer 32:21), toward Israel it is \"brought us out\" (Deu 6:21), and in Jer 21:5 Israel finds itself on Egypt's side of the formula, \"I myself will fight against you with outstretched hand and strong arm, in anger and in fury\"; the hand does not change, the person's position before it changes.", [39], basis="read")
for n in range(47, 57):
    x = [_clean(y) for y in c.by_line[n]["text"].strip().strip("|").split(" | ")]
    S(f"b{n}", f"The context names as the source of the heavy hand, {x[0]}: {x[1]}", [n], basis="read" if n == 56 else "stated")
S("b59", "The heaviness has its source in God's character: the texts name righteousness and justice (Psa 89:14; Dan 9:14, 16) together with steadfast love, faithfulness, the oath, and the cause of the weak; anger is named too, but never as the last word, standing inside a purpose of covenant, atonement and healing.", [59])
S("b61", "Nowhere in this set is the source a hardness in God: Lam 3:33 states outright that the affliction is not from his heart.", [61], kind="silence")
S("r81", "Hardness is felt, and named, by those under the hand; God calls his own hand strong.", [81], basis="read")
S("r82", "The heavy hand is how the hidden, fearful or opposed human experiences the strong hand; the texts separate God's action from his heart (Lam 3:33).", [82], basis="read", verses=["Lam.3.33"], flag="the pointer to M02 unit 2 (Psa 32:3-5; Lam 3:7, 31-33; Isa 59:1-2) is the same line")
c.not_([15, 65], "scope or method or process record", "the limit of the set read and the fuller pass proposed")
